def L(key, lang, **kw):
    i = li(lang)
    if 'item' in kw:
        kw['item'] = ITEMS[kw['item']][i]
    if 'shell' in kw:
        kw['shell'] = (('REAL', 'LIVE') if kw['shell'] else ('SALVA', 'BLANK'))[i]
    if 'got' in kw:
        kw['got'] = ', '.join(ITEMS[k][i] for k in kw['got'])
    return MSG[key][i].format(**kw)


class GameError(Exception):
    def __init__(self, key, **kw):
        super().__init__(key)
        self.key, self.kw = key, kw

    def text(self, lang):
        return L(self.key, lang, **self.kw)


# ====================== UTILITIES ======================
def safe_name(n):
    n = re.sub(r'[^A-Za-z0-9_\-]', '', n.strip().replace(' ', '_'))[:14]
    return n or 'Player'


def hp_bar(hp, mx):
    return '[' + '=' * max(0, hp) + '-' * max(0, mx - hp) + ']'


# ====================== PLAYER AND ROOM ======================
class Player:
    def __init__(self, name, send=None, bot=False, send_data=None):
        self.name, self.send, self.bot = name, send, bot
        self.send_data = send_data
        self.room, self.score, self.lang = None, 0, 'es'
        self.reset(4)

    def reset(self, hp):
        self.hp = self.maxhp = hp
        self.alive, self.cuffed = True, False
        self.items = {k: 0 for k in ITEMS}

    def tell(self, text, kind=None):
        if self.send:
            try:
                self.send(text, kind)
            except Exception:
                pass

    def t(self, key, kind=None, **kw):
        if self.send:
            self.tell(L(key, self.lang, **kw), kind)

    def data(self, d):
        if self.send_data:
            try:
                self.send_data(d)
            except Exception:
                pass


class Room:
    def __init__(self, name, maxp=4, host=None):
        self.name, self.maxp, self.host = name, maxp, host
        self.players, self.started = [], False
        self.lock = threading.RLock()
        self.shotgun, self.live0, self.blank0, self.round, self.loadno = [], 0, 0, 0, 0
        self.current, self.sawed, self.known = None, None, -1
        self.pending, self.shot_id = None, 0
        self.banner_due, self.bot_timer = False, False

    # ---- helpers ----
    def bcast(self, key, kind=None, skip=None, **kw):
        for p in list(self.players):
            if p is not skip:
                p.t(key, kind, **dict(kw))

    def bcast_raw(self, text, kind=None):
        for p in list(self.players):
            p.tell(text, kind)

    def alive_players(self):
        return [p for p in self.players if p.alive]

    def find(self, me, arg):
        others = [q for q in self.alive_players() if q is not me]
        if not arg or arg in ('rival', 'enemy', 'enemigo', 'otro'):
            if len(others) == 1:
                return others[0]
            raise GameError('e_target')
        for q in others:
            if q.name.lower() == arg:
                return q
        for q in others:
            if q.name.lower().startswith(arg):
                return q
        raise GameError('e_notfound', arg=arg)

    def status_text(self, lang):
        i = li(lang)
        n = len(self.shotgun)
        live = sum(self.shotgun)
        o = [L('table', lang, r=self.round),
             L('magazine', lang, bar='[o]' * n, n=n, live=live, blank=n - live)]
        if self.sawed:
            o.append(L('sawed_line', lang, name=self.sawed.name))
        for p in self.players:
            flags = (L('cuffed_tag', lang) if p.cuffed else '') + ('' if p.alive else L('dead_tag', lang))
            o.append('%s %s %s %d/%d HP  %s: %d%s' % (
                '>>' if p is self.current and self.started else '  ', p.name, hp_bar(p.hp, p.maxhp),
                p.hp, p.maxhp, L('wins_lbl', lang), p.score, flags))
            its = ', '.join('%s x%d' % (ITEMS[k][i], v) for k, v in p.items.items() if v)
            o.append('     ' + L('objects', lang) + (its or L('none', lang)))
        return '\n'.join(o)

    def items_text(self, p):
        i = li(p.lang)
        o = [L('your_items', p.lang)]
        for k, v in p.items.items():
            if v:
                o.append('%s x%d (%s) - %s' % (ITEMS[k][i], v, k, ITEMS[k][2 + i]))
        return '\n'.join(o if len(o) > 1 else o + [L('no_items', p.lang)])

    # ---- structured data for the GUI ----
    def snapshot(self, viewer):
        live = sum(self.shotgun)
        cur = self.current if self.started else None
        return {
            'type': 'game', 'room': self.name, 'started': self.started, 'maxp': self.maxp,
            'host': self.host.name if self.host else '', 'you': viewer.name,
            'my_turn': bool(cur is viewer and viewer.alive), 'turn': cur.name if cur else '',
            'pending': bool(self.pending), 'shells': len(self.shotgun), 'live': live,
            'blank': len(self.shotgun) - live, 'live0': self.live0, 'blank0': self.blank0,
            'round': self.round, 'sawed': self.sawed.name if self.sawed else '',
            'players': [{'name': q.name, 'hp': q.hp, 'maxhp': q.maxhp, 'alive': q.alive,
                         'score': q.score, 'cuffed': q.cuffed, 'bot': q.bot, 'turn': q is cur,
                         'items': {k: v for k, v in q.items.items() if v}}
                        for q in self.players]}

    def push_state(self):
        for q in list(self.players):
            if not q.bot:
                q.data(self.snapshot(q))

    # ---- join / leave ----
    def join(self, p):
        with self.lock:
            if self.started:
                raise GameError('e_started')
            if len(self.players) >= self.maxp:
                raise GameError('e_full')
            if any(q.name.lower() == p.name.lower() for q in self.players):
                raise GameError('e_dupname')
            self.players.append(p)
            p.room = self
            if self.host is None and not p.bot:
                self.host = p
            self.bcast('joins', 'info', name=p.name, n=len(self.players), max=self.maxp)
            self.push_state()

    def add_bot(self):
        with self.lock:
            names = [q.name for q in self.players]
            i = 1
            while ('BOT' if i == 1 else 'BOT%d' % i) in names:
                i += 1
            self.join(Player('BOT' if i == 1 else 'BOT%d' % i, bot=True))

    def leave(self, p):
        with self.lock:
            if p not in self.players:
                return
            if self.started:
                p.alive = False
                if self.current is p:
                    self.advance(p)
            self.players.remove(p)
            p.room = None
            self.bcast('leaves', 'warn', name=p.name)
            humans = [q for q in self.players if not q.bot]
            if self.host is p and humans:
                self.host = humans[0]
                self.bcast('newhost', 'info', name=self.host.name)
            if self.started:
                if not humans:
                    self.started, self.pending = False, None
                else:
                    self.after_action()
            self.tick()

    # ---- game ----
    def start(self):
        if len(self.players) < 2:
            raise GameError('e_min2')
        self.started = True
        self.new_game()

    def new_game(self):
        hp = random.randint(3, 5)
        for p in self.players:
            p.reset(hp)
        self.loadno, self.sawed, self.pending = 0, None, None
        self.current = self.players[0]
        self.bcast('newgame', 'info', hp=hp)
        self.new_load()
        self.bcast('starts', None, name=self.current.name)
        self.banner_due = True

    def new_load(self):
        live, blank = random.randint(1, 4), random.randint(1, 4)
        self.shotgun = [1] * live + [0] * blank
        random.shuffle(self.shotgun)
        self.live0, self.blank0, self.known, self.sawed = live, blank, -1, None
        self.round += 1
        self.loadno += 1
        self.bcast('reload', 'warn', live=live, blank=blank)
        keys = list(ITEMS)
        for p in self.alive_players():
            n = random.randint(1, 2) if self.loadno == 1 else random.randint(2, 4)
            got = []
            for _ in range(n):
                if sum(p.items.values()) >= MAX_ITEMS:
                    break
                k = random.choice(keys)
                p.items[k] += 1
                got.append(k)
            if got:
                p.t('got_items', 'info', got=got)
            else:
                p.t('inv_full', 'warn', max=MAX_ITEMS)
        self.bcast('dealt')
        self.banner_due = True

    def advance(self, frm):
        n = len(self.players)
        i = self.players.index(frm)
        for k in range(1, n * 2 + 1):
            c = self.players[(i + k) % n]
            if not c.alive:
                continue
            if c.cuffed:
                c.cuffed = False
                self.bcast('cuff_lost', 'warn', name=c.name)
                c.t('cuff_you', 'warn')
                continue
            self.current = c
            self.banner_due = True
            return

    def hurt(self, p, n):
        p.hp -= n
        if p.hp <= 0:
            p.hp, p.alive = 0, False
            self.bcast('died', 'bad', name=p.name)
            return True
        return False

    def after_action(self):
        alive = self.alive_players()
        if len(alive) <= 1:
            if alive:
                alive[0].score += 1
                self.bcast('wins', 'warn', name=alive[0].name)
            else:
                self.bcast('draw')
            self.started, self.pending = False, None
            self.bcast('over', 'info')
            return False
        if not self.shotgun:
            self.new_load()
        return True

    def banner(self):
        c = self.current
        self.bcast('turn_of', None, skip=c, name=c.name)
        if not c.bot:
            c.t('your_turn', 'warn')
            c.tell(self.status_text(c.lang))
            c.t('hint_turn', 'dim')

    def tick(self):
        self._tick()
        self.push_state()

    def _tick(self):
        if not self.started or self.pending:
            return
        if self.banner_due:
            self.banner_due = False
            self.banner()
        c = self.current
        if c and c.bot and c.alive and not self.bot_timer:
            self.bot_timer = True
            t = threading.Timer(random.uniform(1.5, 3.0), self.bot_run)
            t.daemon = True
            t.start()

    def bot_run(self):
        with self.lock:
            self.bot_timer = False
            if self.started and not self.pending and self.current and self.current.bot and self.current.alive:
                self.bot_act()
            self.tick()

    # ---- shots ----
    def start_shot(self, sh, tg):
        if sh is tg:
            self.bcast('aim_self', 'warn', name=sh.name)
        else:
            self.bcast('aim', 'warn', a=sh.name, b=tg.name)
            tg.t('aimed_you', 'bad', name=sh.name)
        self.shot_id += 1
        self.pending = (self.shot_id, sh, tg)
        t = threading.Timer(random.uniform(2.0, 3.5), self.resolve, args=(self.shot_id,))
        t.daemon = True
        t.start()

    def resolve(self, sid):
        with self.lock:
            if not self.pending or self.pending[0] != sid:
                return
            _, sh, tg = self.pending
            self.pending = None
            if (not self.started or not sh.alive or not tg.alive or self.current is not sh
                    or sh.room is not self or tg.room is not self or not self.shotgun):
                self.bcast('canceled')
            else:
                self.do_shot(sh, tg)
            self.tick()

    def do_shot(self, sh, tg):
        live = self.shotgun.pop(0) == 1
        self.known = -1
        dmg = 2 if self.sawed is sh else 1
        self.sawed = None
        self.bcast_raw('*BANG*' if live else '*click*')
        if sh is tg:
            if live:
                self.bcast('self_live', name=sh.name, dmg=dmg)
                if not self.hurt(tg, dmg):
                    sh.t('hp_left', 'bad', hp=sh.hp, max=sh.maxhp)
                self.advance(sh)
            else:
                self.bcast('self_blank', name=sh.name)
                sh.t('keep_turn', 'good')
                self.banner_due = True
        else:
            if live:
                self.bcast('shot_live', a=sh.name, b=tg.name, dmg=dmg)
                if self.hurt(tg, dmg):
                    sh.t('killed', 'good', name=tg.name)
                else:
                    tg.t('hp_left', 'bad', hp=tg.hp, max=tg.maxhp)
            else:
                self.bcast('shot_blank', a=sh.name, b=tg.name)
            self.advance(sh)
        self.after_action()

    # ---- items ----
    def check(self, u, item, tgt=None, arg2=None, consume=True):
        if consume and u.items[item] <= 0:
            raise GameError('e_noitem', item=item)
        if item == 'cigarettes' and u.hp >= u.maxhp:
            raise GameError('e_fullhp')
        if item == 'handcuffs':
            if tgt is None:
                raise GameError('e_cuffwho')
            if tgt.cuffed:
                raise GameError('e_cuffed', name=tgt.name)
        if item == 'saw' and self.sawed is u:
            raise GameError('e_sawed')
        if item == 'phone' and len(self.shotgun) < 2:
            raise GameError('e_phone')
        if item == 'adrenaline':
            if tgt is None:
                raise GameError('e_stealwho')
            if arg2 not in ITEMS or arg2 == 'adrenaline':
                raise GameError('e_stealitem')
            if tgt.items[arg2] <= 0:
                raise GameError('e_stealnone', name=tgt.name, item=arg2)
            self.check(u, arg2, tgt, None, False)

    def use(self, u, item, tgt=None, arg2=None, consume=True):
        self.check(u, item, tgt, arg2, consume)
        if consume:
            u.items[item] -= 1
        n = u.name
        if item == 'beer':
            sh = self.shotgun.pop(0)
            self.known = -1
            self.bcast('beer_use', name=n, shell=sh)
            self.after_action()
        elif item == 'cigarettes':
            u.hp += 1
            self.bcast('cig_use', name=n)
            u.t('hp_now', 'good', hp=u.hp, max=u.maxhp)
        elif item == 'magnifying':
            self.bcast('mag_use', name=n)
            if u.bot:
                self.known = self.shotgun[0]
            else:
                u.t('mag_see', 'info', shell=self.shotgun[0])
        elif item == 'handcuffs':
            tgt.cuffed = True
            self.bcast('cuff_use', name=n, target=tgt.name)
            tgt.t('cuffed_you', 'bad', name=n)
        elif item == 'saw':
            self.sawed = u
            self.bcast('saw_use', 'warn', name=n)
        elif item == 'phone':
            idx = random.randint(1, len(self.shotgun) - 1)
            self.bcast('phone_use', name=n)
            if not u.bot:
                u.t('phone_see', 'info', n=idx + 1, shell=self.shotgun[idx])
        elif item == 'inverter':
            self.shotgun[0] = 1 - self.shotgun[0]
            if u.bot:
                if self.known >= 0:
                    self.known = 1 - self.known
            else:
                self.known = -1
            self.bcast('inv_use', name=n)
            u.t('inv_you', 'info')
        elif item == 'medicine':
            if random.random() < 0.5:
                u.hp = min(u.maxhp, u.hp + 2)
                self.bcast('med_ok', name=n)
                u.t('med_hp', 'good', hp=u.hp, max=u.maxhp)
            else:
                self.bcast('med_bad', name=n)
                if self.hurt(u, 1):
                    if self.current is u:
                        self.advance(u)
                    self.after_action()
        elif item == 'adrenaline':
            tgt.items[arg2] -= 1
            self.bcast('adr_use', name=n, item=arg2, target=tgt.name)
            tgt.t('adr_you', 'bad', name=n, item=arg2)
            self.use(u, arg2, tgt, None, False)

    # ---- bot ----
    def bot_try(self, b, item, tgt=None, arg2=None):
        try:
            self.use(b, item, tgt, arg2)
            return True
        except GameError:
            return False

    def bot_act(self):
        b = self.current
        opps = [p for p in self.alive_players() if p is not b]
        if not opps or not self.shotgun:
            return
        opp = min(opps, key=lambda p: p.hp)
        live = sum(self.shotgun)
        blank = len(self.shotgun) - live
        k, it, T = self.known, b.items, self.bot_try
        if it['cigarettes'] and b.hp < b.maxhp and T(b, 'cigarettes'): return
        if it['medicine'] and b.maxhp - b.hp >= 2 and b.hp >= 3 and T(b, 'medicine'): return
        if k == -1 and live and blank and it['magnifying'] and T(b, 'magnifying'): return
        if k == 0 and it['inverter'] and T(b, 'inverter'): return
        if k == -1 and live == blank and it['beer'] and T(b, 'beer'): return
        if it['adrenaline']:
            want = []
            if not opp.cuffed and len(self.shotgun) > 1: want.append('handcuffs')
            if self.sawed is not b and (k == 1 or (k == -1 and live > blank)): want.append('saw')
            if k == -1 and live and blank: want.append('magnifying')
            if b.hp < b.maxhp: want.append('cigarettes')
            for w in want:
                if opp.items[w] and T(b, 'adrenaline', opp, w): return
        if k == 1: at_opp = True
        elif k == 0: at_opp = False
        elif live > blank: at_opp = True
        elif live < blank: at_opp = False
        else: at_opp = random.random() < 0.5
        if at_opp:
            if it['handcuffs'] and not opp.cuffed and len(self.shotgun) > 1 and T(b, 'handcuffs', opp): return
            if it['saw'] and self.sawed is not b and (k == 1 or (k == -1 and live > blank)) and T(b, 'saw'): return
            self.start_shot(b, opp)
        else:
            self.start_shot(b, b)

    # ---- commands ----
    def command(self, p, line):
        with self.lock:
            try:
                self._command(p, line)
            except GameError as e:
                p.tell(e.text(p.lang), 'bad')
            self.tick()

    def _command(self, p, line):
        t = line.split()
        c = ALIAS.get(t[0].lower(), t[0].lower())
        a = [x.lower() for x in t[1:]]
        if c in ITEM_ALIAS:
            a, c = [c] + a, 'use'
        if c == 'info': return p.tell(HELP_GAME[p.lang])
        if c == 'rules': return p.tell(RULES[p.lang])
        if c == 'status': return p.tell(self.status_text(p.lang))
        if c == 'items': return p.tell(self.items_text(p))
        if c in ('health', 'stats'):
            return p.tell('\n'.join('%s %s %d/%d HP | %s: %d | %s' % (
                q.name, hp_bar(q.hp, q.maxhp), q.hp, q.maxhp, L('wins_lbl', p.lang), q.score,
                L('alive', p.lang) if q.alive else L('deadw', p.lang))
                for q in self.players))
        if c == 'say':
            txt = line.split(None, 1)[1] if len(t) > 1 else ''
            return self.bcast_raw('[%s] %s' % (p.name, txt), 'info') if txt else None
        if c == 'start':
            if p is not self.host: raise GameError('e_onlyhost', host=self.host.name)
            if self.started: raise GameError('e_running')
            return self.start()
        if c == 'addbot':
            if p is not self.host: raise GameError('e_hostbot')
            return self.add_bot()
        if c not in ('shoot', 'use'):
            raise GameError('e_unknown')
        if not self.started: raise GameError('e_notstarted')
        if not p.alive: raise GameError('e_dead')
        if self.current is not p: raise GameError('e_notturn', name=self.current.name)
        if self.pending: raise GameError('e_pending')
        if c == 'shoot':
            if not a: raise GameError('e_shootuse')
            tgt = p if a[0] in ('me', 'yo', 'self', 'mi') else self.find(p, a[0])
            return self.start_shot(p, tgt)
        if not a or a[0] not in ITEM_ALIAS:
            raise GameError('e_useuse')
        item, tgt, arg2 = ITEM_ALIAS[a[0]], None, None
        if item == 'handcuffs':
            tgt = self.find(p, a[1] if len(a) > 1 else '')
        elif item == 'adrenaline':
            rest = a[1:]
            if not rest or rest[-1] not in ITEM_ALIAS:
                raise GameError('e_aduse')
            arg2 = ITEM_ALIAS[rest.pop()]
            tgt = self.find(p, rest[0] if rest else '')
        self.use(p, item, tgt, arg2)


# ====================== SERVER ======================
class Server:
    def __init__(self, name):
        self.name, self.rooms, self.lock = name, {}, threading.Lock()

    def serve(self, port=TCP_PORT):
        ls = socket.socket()
        ls.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        ls.bind(('', port))
        ls.listen(16)
        threading.Thread(target=self.udp, args=(port,), daemon=True).start()
        while True:
            c, addr = ls.accept()
            threading.Thread(target=Session(c, self, addr).run, daemon=True).start()

    def udp(self, port):
        try:
            s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
            s.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
            s.bind(('', UDP_PORT))
            while True:
                data, addr = s.recvfrom(256)
                if data == b'BUCKSHOT?':
                    info = {'name': self.name, 'port': port, 'rooms': len(self.rooms)}
                    s.sendto(json.dumps(info).encode(), addr)
        except OSError:
            pass

    def drop_if_empty(self, room):
        with self.lock:
            if room and not any(not q.bot for q in room.players):
                self.rooms.pop(room.name.lower(), None)


class Session:
    count = 0

    def __init__(self, sock, server, addr):
        Session.count += 1
        self.sock, self.server, self.wlock = sock, server, threading.Lock()
        self.welcomed = False
        self.player = Player('Player%d' % Session.count, send=self.send, send_data=self.send_data)

    def send(self, text, kind=None):
        data = (json.dumps({'m': text, 'k': kind}) + '\n').encode('utf-8')
        with self.wlock:
            self.sock.sendall(data)

    def send_data(self, d):
        data = (json.dumps({'d': d}) + '\n').encode('utf-8')
        with self.wlock:
            self.sock.sendall(data)

    def run(self):
        p = self.player
        try:
            p.data({'type': 'lobby'})
            for line in self.sock.makefile('r', encoding='utf-8'):
                try:
                    cmd = json.loads(line).get('c', '').strip()
                except ValueError:
                    continue
                if not cmd:
                    continue
                try:
                    if not self.handle(cmd):
                        break
                except GameError as e:
                    p.tell(e.text(p.lang), 'bad')
        except OSError:
            pass
        finally:
            room = p.room
            if room:
                room.leave(p)
                self.server.drop_if_empty(room)
            self.sock.close()

    def handle(self, line):
        p, srv = self.player, self.server
        t = line.split()
        c = ALIAS.get(t[0].lower(), t[0].lower())
        if c in ('quit', 'exit'):
            return False
        if c == 'lang':
            p.lang = 'en' if len(t) > 1 and t[1].lower() == 'en' else 'es'
            if not self.welcomed:
                self.welcomed = True
                p.tell(L('welcome', p.lang, srv=srv.name, name=p.name) + '\n' + HELP_LOBBY[p.lang], 'info')
            return True
        if c == 'name':
            if len(t) < 2: raise GameError('e_nameusage')
            new = safe_name(t[1])
            if p.room and any(q is not p and q.name.lower() == new.lower() for q in p.room.players):
                raise GameError('e_nameuse')
            old, p.name = p.name, new
            p.t('rename', 'good', name=new)
            if p.room:
                p.room.bcast('renamed', 'info', skip=p, old=old, new=new)
                p.room.push_state()
            return True
        if p.room:
            if c == 'leave':
                room = p.room
                room.leave(p)
                srv.drop_if_empty(room)
                p.tell(L('back_lobby', p.lang) + '\n' + HELP_LOBBY[p.lang], 'info')
                p.data({'type': 'lobby'})
            else:
                p.room.command(p, line)
            return True
        if c == 'info':
            p.tell(HELP_LOBBY[p.lang])
        elif c == 'rules':
            p.tell(RULES[p.lang])
        elif c in ('rooms', 'roomsdata'):
            with srv.lock:
                rs = list(srv.rooms.values())
            p.data({'type': 'rooms', 'rooms': [
                {'name': r.name, 'n': len(r.players), 'max': r.maxp, 'started': r.started,
                 'host': r.host.name if r.host else '-'} for r in rs]})
            if c == 'roomsdata':
                return True
            if not rs:
                p.t('no_rooms', 'warn')
                return True
            o = [L('rooms_hdr', p.lang)]
            for r in rs:
                o.append('%-12s %d/%d  %s  %s: %s  [%s]' % (
                    r.name, len(r.players), r.maxp, L('playing' if r.started else 'waiting', p.lang),
                    L('hostlbl', p.lang), r.host.name if r.host else '-', ', '.join(q.name for q in r.players)))
            p.tell('\n'.join(o))
        elif c == 'create':
            if len(t) < 2: raise GameError('e_createusage')
            name = safe_name(t[1])
            mx = int(t[2]) if len(t) > 2 and t[2].isdigit() else 4
            with srv.lock:
                if name.lower() in srv.rooms: raise GameError('e_roomexists')
                room = Room(name, max(2, min(8, mx)), p)
                srv.rooms[name.lower()] = room
            room.join(p)
            p.tell(L('created', p.lang) + '\n' + HELP_GAME[p.lang], 'good')
        elif c == 'join':
            if len(t) < 2: raise GameError('e_joinusage')
            with srv.lock:
                room = srv.rooms.get(t[1].lower())
            if not room: raise GameError('e_noroom')
            room.join(p)
            p.t('joined', 'good', name=room.name)
        else:
            raise GameError('e_lobbyunknown')
        return True


# ====================== NETWORK UTILITIES ======================
def local_ip():
    try:
        s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        s.connect(('10.255.255.255', 1))
        return s.getsockname()[0]
    except OSError:
        return '127.0.0.1'


def discover(timeout=1.5):
    found = {}
    try:
        s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        s.setsockopt(socket.SOL_SOCKET, socket.SO_BROADCAST, 1)
        s.settimeout(0.4)
        s.sendto(b'BUCKSHOT?', ('255.255.255.255', UDP_PORT))
        end = time.time() + timeout
        while time.time() < end:
            try:
                data, addr = s.recvfrom(512)
                found[addr[0]] = json.loads(data.decode())
            except socket.timeout:
                pass
    except (OSError, ValueError):
        pass
    return found


