# --- SPLASH MP3 END ---


def _tone(f0, f1, dur, vol=0.6, decay=4.0, square=False):
    n = int(SR * dur)
    out, ph = [], 0.0
    for i in range(n):
        k = i / n
        ph += 2 * math.pi * (f0 + (f1 - f0) * k) / SR
        v = math.sin(ph)
        if square:
            v = 0.5 if v >= 0 else -0.5
        out.append(v * vol * math.exp(-decay * k))
    return out


def _noise(dur, vol=0.8, decay=6.0, alpha=1.0):
    n = int(SR * dur)
    out, y = [], 0.0
    for i in range(n):
        y += alpha * (random.uniform(-1, 1) - y)
        out.append(y * vol * math.exp(-decay * i / n))
    return out


def _mix(*parts):
    n = max(len(p) for p in parts)
    return [sum(p[i] for p in parts if i < len(p)) for i in range(n)]


def _seq(*items):
    """items: (start_seconds, samples)"""
    n = max(int(a * SR) + len(p) for a, p in items)
    out = [0.0] * n
    for a, p in items:
        o = int(a * SR)
        for i, v in enumerate(p):
            out[o + i] += v
    return out


def _build_sounds():
    click = lambda a: _mix(_noise(0.035, 0.7, 12, a), _tone(2200, 1400, 0.035, 0.25, 8))
    return {
        'select': _tone(660, 900, 0.07, 0.35, 3, True),
        'start': _seq((0, _tone(440, 440, 0.09, 0.35, 1, True)), (0.09, _tone(554, 554, 0.09, 0.35, 1, True)),
                      (0.18, _tone(659, 659, 0.09, 0.35, 1, True)), (0.27, _tone(880, 880, 0.30, 0.4, 3, True))),
        'bang': _mix(_noise(0.55, 0.9, 6, 0.35), _tone(130, 40, 0.45, 0.9, 5)),
        'click': click(1.0),
        'reload': _seq((0, click(0.6)), (0.14, click(0.9)), (0.30, _tone(200, 120, 0.12, 0.4, 5))),
        'death': _mix(_tone(330, 50, 0.8, 0.6, 2.5), _noise(0.25, 0.3, 8, 0.3)),
        'win': _seq((0, _tone(523, 523, 0.14, 0.4, 1.5, True)), (0.13, _tone(659, 659, 0.14, 0.4, 1.5, True)),
                    (0.26, _tone(784, 784, 0.14, 0.4, 1.5, True)), (0.39, _tone(1047, 1047, 0.5, 0.45, 3, True))),
        'intro': _mix(_tone(55, 160, 1.4, 0.7, 1.2), _noise(1.4, 0.25, 2.5, 0.06)),
    }


class Sfx:
    """Generates all sounds at startup into a temp folder and plays them (winsound / afplay / paplay / aplay)."""
    def __init__(self):
        self.on, self.ready, self.files, self.dir = True, False, {}, None
        self.music, self.mproc, self.want, self.mfail = None, None, False, False

    def load(self):
        threading.Thread(target=self._gen, daemon=True).start()

    def _gen(self):
        try:
            self.dir = tempfile.mkdtemp(prefix='buckshot_')
            for name, samples in _build_sounds().items():
                path = os.path.join(self.dir, name + '.wav')
                data = array.array('h', (int(max(-1.0, min(1.0, v)) * 32000) for v in samples))
                if sys.byteorder == 'big':
                    data.byteswap()
                with wave.open(path, 'wb') as w:
                    w.setnchannels(1)
                    w.setsampwidth(2)
                    w.setframerate(SR)
                    w.writeframes(data.tobytes())
                self.files[name] = path
            if SPLASH_MP3.strip():
                self.music = os.path.join(self.dir, 'splash.mp3')
                with open(self.music, 'wb') as f:
                    f.write(base64.b64decode(''.join(SPLASH_MP3.split())))
            self.ready = True
        except Exception:
            self.ready = False

    def play(self, name):
        path = self.files.get(name)
        if not self.on or not self.ready or not path:
            return
        try:
            if sys.platform.startswith('win'):
                import winsound
                winsound.PlaySound(path, winsound.SND_FILENAME | winsound.SND_ASYNC)
            else:
                cmd = ['afplay'] if sys.platform == 'darwin' else None
                if cmd is None:
                    for c, extra in (('paplay', []), ('aplay', ['-q']), ('play', ['-q'])):
                        if shutil.which(c):
                            cmd = [c] + extra
                            break
                if cmd:
                    subprocess.Popen(cmd + [path], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        except Exception:
            pass

    def play_music(self):
        """MP3 playback: Windows (MCI, built in), macOS (afplay) or Linux (mpg123/ffplay/mpv/cvlc)."""
        if not self.on or not self.ready or not self.music or self.mfail:
            return
        self.stop_music()
        try:
            if sys.platform.startswith('win'):
                import ctypes
                mci = ctypes.windll.winmm.mciSendStringW
                if mci('open "%s" type mpegvideo alias bsplash' % self.music, None, 0, 0) == 0:
                    mci('play bsplash', None, 0, 0)
                else:
                    self.mfail = True
            else:
                cmds = [('afplay', [])] if sys.platform == 'darwin' else [
                    ('mpg123', ['-q']), ('ffplay', ['-nodisp', '-autoexit', '-loglevel', 'quiet']),
                    ('mpv', ['--no-video', '--really-quiet']), ('cvlc', ['--play-and-exit', '-q'])]
                for c, extra in cmds:
                    if shutil.which(c):
                        self.mproc = subprocess.Popen([c] + extra + [self.music], stdout=subprocess.DEVNULL,
                                                      stderr=subprocess.DEVNULL)
                        break
        except Exception:
            pass

    def stop_music(self):
        try:
            if sys.platform.startswith('win'):
                import ctypes
                mci = ctypes.windll.winmm.mciSendStringW
                mci('stop bsplash', None, 0, 0)
                mci('close bsplash', None, 0, 0)
            elif self.mproc:
                self.mproc.terminate()
        except Exception:
            pass
        self.mproc = None

    def _playing(self):
        try:
            if sys.platform.startswith('win'):
                import ctypes
                buf = ctypes.create_unicode_buffer(32)
                ctypes.windll.winmm.mciSendStringW('status bsplash mode', buf, 32, 0)
                return buf.value == 'playing'
            return self.mproc is not None and self.mproc.poll() is None
        except Exception:
            return False

    def music_start(self):
        """Start the looping music (does nothing if it is already playing)."""
        if not self.on or not self.music:
            return
        self.want = True
        if not self._playing():
            self.play_music()

    def music_stop(self):
        self.want = False
        self.stop_music()

    def music_tick(self):
        """Called every 0.5 s: restarts the track when it ends (loop)."""
        if self.want and self.on and self.ready and self.music and not self._playing():
            self.play_music()

    def close(self):
        self.want = False
        self.stop_music()
        if self.dir:
            shutil.rmtree(self.dir, ignore_errors=True)


