# ---------- visual effects ----------
def mix(c1, c2, a):
    """Blend two '#rrggbb' colors (a=0 -> c1, a=1 -> c2)."""
    a = max(0.0, min(1.0, a))
    x, y = int(c1[1:], 16), int(c2[1:], 16)
    return '#%02x%02x%02x' % tuple(int(((x >> s) & 255) * (1 - a) + ((y >> s) & 255) * a) for s in (16, 8, 0))


def clamp(v):
    return max(0.0, min(1.0, v))


def glitch(s, p):
    return ''.join(random.choice('▓▒░#@%&01') if ch != ' ' and random.random() < p else ch for ch in s)


