def bigh(text):
    """Hollow (double-line outline) 5-row letters, same 6-wide cells as big()."""
    gl = [_GH.get(ch, _GH[' ']).split('|') for ch in text.upper()]
    return [' '.join(g[i] for g in gl) for i in range(5)]


def big(text):
    """Block letters, 5 rows, all rows the same width (no trailing space, so it centers exactly)."""
    gl = [_G.get(ch, _G[' ']).split('|') for ch in text.upper()]
    return [' '.join(g[i] for g in gl) for i in range(5)]


