TOPO_COLS = ['#222222', '#343434', '#4f4f4f', '#7d7d7d', '#a0a0a0']   # white/grey variants (splash + menu map)
RAMP = '.,:;-=+*#%'


class Topo:
    """ASCII topographic map: periodic value noise (scrolls seamlessly)."""
    W, H = 240, 100

    def __init__(self, seed=7):
        rnd = random.Random(seed)
        h = [[0.0] * self.W for _ in range(self.H)]
        amp = 1.0
        for cw, ch in ((6, 3), (12, 6), (24, 12)):
            lat = [[rnd.random() for _ in range(cw)] for _ in range(ch)]
            sx, sy = self.W / cw, self.H / ch
            for y in range(self.H):
                fy = y / sy
                y0 = int(fy)
                ty = fy - y0
                ty = ty * ty * (3 - 2 * ty)
                ya, yb = lat[y0 % ch], lat[(y0 + 1) % ch]
                row = h[y]
                for x in range(self.W):
                    fx = x / sx
                    x0 = int(fx)
                    tx = fx - x0
                    tx = tx * tx * (3 - 2 * tx)
                    a = ya[x0 % cw] + (ya[(x0 + 1) % cw] - ya[x0 % cw]) * tx
                    b = yb[x0 % cw] + (yb[(x0 + 1) % cw] - yb[x0 % cw]) * tx
                    row[x] += (a + (b - a) * ty) * amp
            amp *= 0.5
        lo, hi = min(map(min, h)), max(map(max, h))
        self.h = [[(v - lo) / (hi - lo) * 0.999 for v in r] for r in h]

    def frame(self, cols, rows, ox, oy, t):
        N, sh = 10, 0.05 * math.sin(t * 0.5)
        H, W, HH = self.h, self.W, self.H
        lv = [[int((H[(oy + y) % HH][(ox + x) % W] + sh) * N) for x in range(cols + 1)] for y in range(rows + 1)]
        Ls = [[[' '] * cols for _ in range(rows)] for _ in range(5)]
        ph = int(t * 2)
        for y in range(rows):
            a, b = lv[y], lv[y + 1]
            for x in range(cols):
                e = a[x]
                if a[x + 1] != e or b[x] != e:
                    Ls[1 if e < 4 else (2 if e < 7 else 3)][y][x] = RAMP[min(max(e, 0), 9)]
                elif e <= 2:
                    if (x + y + ph) % 4 == 0:
                        Ls[0][y][x] = '~'
                elif e >= 8 and (x + y) % 2 == 0:
                    Ls[4][y][x] = '^'
        return [''.join(r) for layer in Ls for r in layer]


class TopoBG:
    """Paints the animated map on a Canvas and calls hook(t, w, h) every frame."""
    def __init__(self, canvas, topo, hook=None, fade=1.0, ms=90):
        self.c, self.topo, self.hook, self.fade, self.ms = canvas, topo, hook, fade, ms
        self.f = tkfont.Font(family=MONO, size=9)
        self.cw, self.lh = max(1, self.f.measure('M')), self.f.metrics('linespace')
        self.items, self.size, self.t0 = [], (0, 0), time.time()
        self.cols = self.rows = 0
        canvas.after(10, self.tick)

    def build(self, w, h):
        for it in self.items:
            self.c.delete(it)
        self.cols, self.rows = w // self.cw + 2, h // self.lh + 2
        self.items = [self.c.create_text(0, y * self.lh, anchor='nw', text='', font=self.f, fill=col,
                                         tags=('topo', 'topo%d' % k))
                      for k, col in enumerate(TOPO_COLS) for y in range(self.rows)]
        self.c.tag_lower('topo')

    def tick(self):
        try:
            if not self.c.winfo_exists():
                return
            w, h = self.c.winfo_width(), self.c.winfo_height()
            t = time.time() - self.t0
            if w > 50 and (w, h) != self.size:
                self.size = (w, h)
                self.build(w, h)
            if self.items:
                rows = self.topo.frame(self.cols, self.rows, int(t * 3), int(t * 1.2), t)
                for it, s in zip(self.items, rows):
                    self.c.itemconfig(it, text=s)
                for k, col in enumerate(TOPO_COLS):
                    self.c.itemconfig('topo%d' % k, fill=mix(BG, col, self.fade))
            if self.hook:
                self.hook(t, w, h)
        except tk.TclError:
            return
        self.c.after(self.ms, self.tick)


class Logo:
    """Block-letter logo with shadow; each row has its own color (staggered fade)."""
    def __init__(self, c, font, text='BUCKSHOT', hollow=False):
        self.c, self.lines = c, (bigh(text) if hollow else big(text))
        self.so = 2 if hollow else 3
        self.lh = font.metrics('linespace')
        self.h = self.lh * len(self.lines)
        self.sh = [c.create_text(0, 0, text=l, font=font, fill=BG) for l in self.lines]
        self.mn = [c.create_text(0, 0, text=l, font=font, fill=BG) for l in self.lines]

    def place(self, cx, top):
        for i in range(len(self.lines)):
            y = top + (i + 0.5) * self.lh
            self.c.coords(self.mn[i], cx, y)
            self.c.coords(self.sh[i], cx + self.so, y + self.so)

    def swept(self, i, ph, pitch=7, delay=0.13, dur=0.7):
        """Row i with the 'hollow sweep': each letter empties in turn, the next follows, then each recovers."""
        s = self.lines[i]
        if ph is None or ph < 0 or ph > 3:
            return s
        out = list(s)
        for j in range((len(s) + 1) // pitch):
            u = (ph - j * delay) / dur
            if 0 <= u < 1:
                ch = '▓' if u < 0.12 else ('░' if u < 0.78 else '▒')
                for x in range(j * pitch, min(len(s), j * pitch + pitch - 1)):
                    if out[x] != ' ':
                        out[x] = ch
        return ''.join(out)

    def set(self, i, text, col, shadow):
        self.c.itemconfig(self.mn[i], text=text, fill=col)
        self.c.itemconfig(self.sh[i], text=self.lines[i], fill=shadow)


class Tip:
    def __init__(self, w, text):
        self.w, self.text, self.tw = w, text, None
        w.bind('<Enter>', self.show)
        w.bind('<Leave>', self.hide)
        w.bind('<Destroy>', self.hide)

    def show(self, e=None):
        self.hide()
        self.tw = tk.Toplevel(self.w)
        self.tw.wm_overrideredirect(True)
        self.tw.wm_geometry('+%d+%d' % (self.w.winfo_rootx() + 8, self.w.winfo_rooty() - 28))
        tk.Label(self.tw, text=self.text, bg='#222', fg='#fff', font=SMALL, padx=6, pady=2,
                 relief='solid', borderwidth=1).pack()

    def hide(self, e=None):
        if self.tw:
            self.tw.destroy()
            self.tw = None


# ====================== BACKENDS ======================
class LocalBackend:
    """Local game against bots: uses the engine directly."""
    def __init__(self, name, bots, lang, put_text, put_data):
        self.p = Player(name, send=put_text, send_data=put_data)
        self.p.lang = lang
        self.room = Room('local', 4, self.p)
        self.room.join(self.p)
        for _ in range(bots):
            self.room.add_bot()
        with self.room.lock:
            self.room.start()
            self.room.tick()

    def send(self, line):
        self.room.command(self.p, line)

    def close(self):
        self.room.leave(self.p)


class NetBackend:
    def __init__(self, ip, port, name, lang, put_text, put_data, on_close):
        self.sock = socket.create_connection((ip, port), timeout=5)
        self.sock.settimeout(None)
        self.wlock, self.dead = threading.Lock(), False
        threading.Thread(target=self._recv, args=(put_text, put_data, on_close), daemon=True).start()
        self.send('lang ' + lang)
        self.send('name ' + name)

    def send(self, line):
        with self.wlock:
            self.sock.sendall((json.dumps({'c': line}) + '\n').encode('utf-8'))

    def _recv(self, put_text, put_data, on_close):
        try:
            for line in self.sock.makefile('r', encoding='utf-8'):
                m = json.loads(line)
                if 'm' in m:
                    put_text(m['m'], m.get('k'))
                elif 'd' in m:
                    put_data(m['d'])
        except (OSError, ValueError):
            pass
        if not self.dead:
            on_close()

    def close(self):
        self.dead = True
        try:
            self.send('quit')
            self.sock.close()
        except OSError:
            pass


# ====================== APPLICATION ======================
class App:
    def __init__(self):
        self.root = tk.Tk()
        self.root.title('BUCKSHOT')
        self.root.geometry('1120x700')
        self.root.minsize(900, 560)
        try:
            self.root.state('zoomed')              # Windows
        except tk.TclError:
            try:
                self.root.attributes('-zoomed', True)   # Linux
            except tk.TclError:                    # macOS / others
                self.root.geometry('%dx%d+0+0' % (self.root.winfo_screenwidth(),
                                                  self.root.winfo_screenheight() - 80))
        self.root.configure(bg=BG)
        self.root.protocol('WM_DELETE_WINDOW', self.quit)
        self.q = queue.Queue()
        self.lang = 'es'
        self.backend, self.local, self.mode = None, False, 'menu'
        self.server_started, self.lobby_loop = False, False
        self.name_var = tk.StringVar(value='Player')
        self.bots_var = tk.IntVar(value=1)
        self.hist, self.hi, self.last_acts = [], 0, None
        self.rooms = []
        self.menu_page, self.menu_msg = 'main', None
        self.gen, self.ov, self.turn_on, self.menu_sz = 0, None, False, None
        self.topo = Topo(7)
        SFX.load()
        self.s_snd = False
        self.root.after(50, self.poll)
        self.root.after(500, self.music_loop)
        self.show_splash()

    # ---- helpers ----
    def u(self, key, **kw):
        return UI[key][li(self.lang)].format(**kw)

    def iname(self, k):
        return ITEMS[k][li(self.lang)]

    def clear(self):
        self.gen += 1
        self.ov = None
        for w in self.root.winfo_children():
            w.destroy()

    def put_text(self, text, kind=None):
        self.q.put(('t', text, kind))

    def put_data(self, d):
        self.q.put(('d', d))

    def drain(self):
        while not self.q.empty():
            self.q.get_nowait()

    def pname(self):
        return safe_name(self.name_var.get() or 'Player')

    def btn(self, parent, text, cmd, fg='#ddd', bd='#666', font=SMALL, pady=3):
        def go():
            SFX.play('select')
            cmd()
        return tk.Button(parent, text=text, command=go, bg='#111', fg=fg, activebackground='#2a2a2a',
                         activeforeground=fg, font=font, relief='solid', bd=1, highlightbackground=bd,
                         padx=8, pady=pady, cursor='hand2')

    def quit(self):
        if self.backend:
            self.backend.close()
        SFX.close()
        self.root.destroy()

    def exit_to_menu(self):
        if self.backend:
            self.backend.close()
        self.backend = None
        self.show_menu()

    def music_loop(self):
        SFX.music_tick()
        self.root.after(500, self.music_loop)

    def toggle_sound(self):
        SFX.on = not SFX.on
        self.snd_btn.config(text=self.u('snd_on' if SFX.on else 'snd_off'))
        if SFX.on:
            SFX.play('select')
            SFX.music_start()
        else:
            SFX.music_stop()

    def toggle_lang(self):
        self.lang = 'en' if self.lang == 'es' else 'es'
        self.show_menu(self.menu_page)

    # ---- fades (window alpha; silently ignored if unsupported) ----
    def fade(self, a0, a1, ms, done=None):
        self._fid = getattr(self, '_fid', 0) + 1
        tok, steps = self._fid, max(1, ms // 22)

        def step(i=0):
            if tok != self._fid:
                return
            try:
                self.root.attributes('-alpha', a0 + (a1 - a0) * i / steps)
            except tk.TclError:
                i = steps
            if i >= steps:
                if done:
                    done()
            else:
                self.root.after(22, step, i + 1)
        step()

    def fade_in(self):
        self.fade(0.0, 1.0, 260)

    # ---- splash ----
    def show_splash(self):
        self.mode = 'splash'
        self.s_snd = False
        self.clear()
        c = tk.Canvas(self.root, bg=BG, highlightthickness=0)
        c.place(x=0, y=0, relwidth=1, relheight=1)
        self.splash = c
        self.logo = Logo(c, tkfont.Font(family=MONO, size=15, weight='bold'))
        self.s_tag = c.create_text(0, 0, text='', fill=BG, font=(MONO, 12))
        self.s_bar = c.create_text(0, 0, text='', fill=BG, font=FONT)
        self.s_hint = c.create_text(0, 0, text=self.u('anykey'), fill=BG, font=FONT)
        self.splash_ready = False
        self.sbg = TopoBG(c, self.topo, hook=self.splash_tick, fade=0.0, ms=60)
        self.root.bind('<Key>', self.splash_key)
        self.root.bind('<Button-1>', self.splash_key)

    def splash_tick(self, t, w, h):
        c, lg = self.splash, self.logo
        top = h * 0.5 - lg.h * 0.75
        lg.place(w / 2, top)
        self.sbg.fade = clamp((t - 0.8) / 2.5)
        gl = 0.45 * (1 - clamp((t - 1.1) / 1.8))
        if t > 0.3 and not self.s_snd and SFX.ready:
            self.s_snd = True
            if SFX.music:
                SFX.music_start()
            else:
                SFX.play('intro')
        ph = (t - 3.2) % 3.0 if t > 3.2 else None
        for i, ln in enumerate(lg.lines):
            a = clamp((t - 1.1 - 0.15 * i) / 0.6)
            p = gl if (a < 1 or t < 2.9) else (0.12 if random.random() < 0.03 else 0)
            ln = lg.swept(i, ph)
            lg.set(i, glitch(ln, p) if p else ln, mix(BG, '#ff5555', a), mix(BG, '#4a0f0f', a))
        y = top + lg.h + 30
        tag = self.u('tagline')
        c.coords(self.s_tag, w / 2, y)
        c.itemconfig(self.s_tag, text=tag[:int(max(0, t - 2.4) * 25)], fill='#aaaaaa')
        pct = clamp((t - 1.0) / 2.4)
        k = int(pct * 30)
        c.coords(self.s_bar, w / 2, y + 40)
        c.itemconfig(self.s_bar, text='%s  [%s%s] %3d%%' % (self.u('loading'), '█' * k, '░' * (30 - k), pct * 100),
                     fill=mix(BG, '#55ffff', clamp((t - 1.0) / 0.5)))
        if t > SPLASH_READY:
            self.splash_ready = True
            c.coords(self.s_hint, w / 2, y + 80)
            c.itemconfig(self.s_hint, fill=mix(BG, '#ffff55', 0.5 + 0.5 * math.sin(t * 5)))

    def splash_key(self, e=None):
        if self.splash_ready:      # only after the intro animation has played
            self.splash_done()

    def splash_done(self):
        if self.mode != 'splash':
            return
        self.mode = 'menu'
        self.root.unbind('<Key>')
        self.root.unbind('<Button-1>')
        self.fade(1.0, 0.0, 300, self.show_menu)

    # ---- menu: animated map background ----
    def menu_tick(self, t, w, h):
        lg = self.logo
        lg.place(w / 2, 22)
        k = 0.5 + 0.5 * math.sin(t * 2)
        ph = (t + 3.0) % 6.0
        for i in range(len(lg.lines)):
            ln = lg.swept(i, ph)
            g = random.random() < 0.004
            lg.set(i, glitch(ln, 0.15) if g else ln, mix('#d0d0d0', '#ffffff', k), '#2b2b2b')
        if (w, h) != self.menu_sz:
            self.menu_sz = (w, h)
            self.layout_menu(w, 22 + lg.h + 36, h)

    # ---- game effects ----
    def pulse(self, g):
        try:
            if g != self.gen or not self.banner.winfo_exists():
                return
            if self.turn_on:
                self.banner.config(bg=mix('#3d3d00', '#777700', (1 + math.sin(time.time() * 5)) / 2))
        except (tk.TclError, AttributeError):
            return
        self.root.after(60, self.pulse, g)

    def deco(self, line):
        """Decorates engine text: framed headers, health bars, magazine blocks."""
        if line.startswith('> '):
            return line
        m = re.match(r'^--- (.*?) ---$', line)
        if m:
            return '══╡ %s ╞%s' % (m.group(1), '═' * max(2, 40 - len(m.group(1))))
        line = re.sub(r'\[([=-]{2,})\]', lambda m: '▕%s%s▏' % ('█' * m.group(1).count('='),
                                                                 '░' * m.group(1).count('-')), line)
        return line.replace('[o]', '▮')

    def overlay(self, art, color, ms=900, hold=0.4, shake=False):
        """Big ASCII art over the console that fades away."""
        con = getattr(self, 'con', None)
        try:
            if not con or not con.winfo_exists():
                return
            if self.ov:
                try:
                    self.ov.destroy()
                except tk.TclError:
                    pass
            lb = tk.Label(con, text=art, font=(MONO, 12, 'bold'), fg=color, bg=BG, justify='center', bd=0)
            lb.place(relx=0.5, rely=0.42, anchor='center')
        except tk.TclError:
            return
        self.ov, steps = lb, 14

        def step(i=0):
            try:
                if not lb.winfo_exists():
                    return
                if i >= steps:
                    lb.destroy()
                    return
                f = i / steps
                lb.config(fg=mix(BG, color, 1.0 if f < hold else 1 - (f - hold) / (1 - hold)))
                lb.place_configure(relx=0.5 + (random.uniform(-0.012, 0.012) if shake and f < hold else 0))
            except tk.TclError:
                return
            self.root.after(ms // steps, step, i + 1)
        step()

    def recoil(self):
        g = getattr(self, 'gunart', None)
        try:
            if not g or not g.winfo_exists():
                return
            g.move('art', -10, 0)
            g.itemconfig('flash', state='normal')
            self.root.after(90, lambda: g.winfo_exists() and g.move('art', 5, 0))
            self.root.after(190, lambda: g.winfo_exists() and (g.move('art', 5, 0), g.itemconfig('flash', state='hidden')))
        except tk.TclError:
            pass

    def fx(self, text):
        if '*BANG*' in text:
            self.overlay('\n'.join(big('BANG')), '#ff4444', 900, 0.35, True)
            self.flash('#3a0000')
            self.recoil()
            SFX.play('bang')
        elif '*click*' in text:
            self.overlay('\n'.join(big('CLICK')), '#55ff55', 700, 0.3)
            self.flash('#002a00')
            SFX.play('click')
        elif 'ha muerto' in text or 'has died' in text:
            self.root.after(300, lambda: SFX.play('death'))
            self.root.after(450, lambda: self.overlay(SKULL, '#ff5555', 1500, 0.5))
        elif '*** ' in text and ('GANA' in text or 'WINS' in text):
            self.root.after(300, lambda: SFX.play('win'))
            m = re.search(r'\*\*\* (.*?) \*\*\*', text)
            self.root.after(450, lambda: self.overlay(TROPHY + '\n\n' + (m.group(1) if m else ''),
                                                      '#ffff55', 2600, 0.6))
        elif text.startswith('NUEVA PARTIDA') or text.startswith('NEW GAME'):
            SFX.play('start')
        elif text.startswith('RECARGA:') or text.startswith('RELOAD:'):
            SFX.play('reload')
            self.overlay('\n'.join(big('RECARGA' if text.startswith('RECARGA') else 'RELOAD')),
                         '#ffff55', 1100, 0.4)

    def fadein_text(self, start, col):
        """New console lines fade in from black."""
        self._tid = getattr(self, '_tid', 0) + 1
        name, c = 'fd%d' % self._tid, self.con
        c.tag_add(name, start, 'end-1c')
        c.tag_config(name, foreground=BG)

        def step(i=1):
            try:
                if not c.winfo_exists():
                    return
                if i > 5:
                    c.tag_delete(name)
                    return
                c.tag_config(name, foreground=mix(BG, col, i / 5))
            except tk.TclError:
                return
            self.root.after(40, step, i + 1)
        self.root.after(30, step)

    # ---- event queue (threads -> Tk) ----
    def poll(self):
        try:
            while True:
                it = self.q.get_nowait()
                if it[0] == 't' and self.mode in ('game', 'lobby'):
                    self.write(it[1], it[2])
                elif it[0] == 'd' and self.mode in ('game', 'lobby'):
                    self.on_data(it[1])
                elif it[0] == 'closed' and self.mode in ('game', 'lobby'):
                    messagebox.showinfo('BUCKSHOT', self.u('closed'))
                    self.exit_to_menu()
        except queue.Empty:
            pass
        self.root.after(50, self.poll)

    # ================= MENU =================
    def show_menu(self, page='main'):
        self.mode = 'menu'
        self.menu_page = page
        self.clear()
        self.menu_sz = None
        c = tk.Canvas(self.root, bg=BG, highlightthickness=0)
        c.place(x=0, y=0, relwidth=1, relheight=1)
        self.bgc = c
        self.logo = Logo(c, tkfont.Font(family=MONO, size=14, weight='bold'), hollow=True)
        self.bg = TopoBG(c, self.topo, hook=self.menu_tick, ms=90)
        self.btn(self.root, self.u('lang_btn'), self.toggle_lang, '#ffff55', '#888833').place(
            relx=1.0, x=-14, y=12, anchor='ne')
        self.snd_btn = self.btn(self.root, self.u('snd_on' if SFX.on else 'snd_off'), self.toggle_sound,
                                '#55ffff', '#338888')
        self.snd_btn.place(x=14, y=12, anchor='nw')
        self.build_menu_panel(page)
        SFX.music_start()
        self.fade_in()

    def menu_goto(self, page):
        """Switch between the menu pages (main / single / multi)."""
        self.menu_page = page
        self.menu_sz = None            # menu_tick re-lays out the new page
        self.build_menu_panel(page)

    def go_splash(self):
        if self.backend:
            self.backend.close()
            self.backend = None
        self.show_splash()

    # ---- menu items are plain ASCII text drawn straight on the animated map (no boxes, no background) ----
    def m_text(self, text, col, font, h):
        i = self.bgc.create_text(0, 0, text=text, fill=col, font=font, tags='mnu', state='hidden')
        self.menu_rows.append(([(i, 'center', 0)], h))
        return i

    def m_option(self, text, cmd, col, art=False):
        if not art:
            return self.m_option_plain(text, cmd, col)
        c = self.bgc
        art = big3(text)
        white, hot, shade = '#ffffff', '#ffe98a', '#2b2b2b'
        sh = c.create_text(0, 0, text='\n'.join(art), fill=shade, font=(MONO, 10, 'bold'), justify='center',
                           tags='mnu', state='hidden')
        i = c.create_text(0, 0, text='\n'.join(art), fill=white, font=(MONO, 10, 'bold'), justify='center',
                          tags='mnu', state='hidden')
        self.m_art[i] = (art, sh)

        def marked():
            return '\n'.join(('>> ' if k == 1 else '   ') + ln + (' <<' if k == 1 else '   ')
                             for k, ln in enumerate(art))

        def enter(e):
            c.itemconfig(i, text=marked(), fill=hot)
            c.itemconfig(sh, text=marked())
            c.config(cursor='hand2')

        def leave(e):
            c.itemconfig(i, text='\n'.join(art), fill=white)
            c.itemconfig(sh, text='\n'.join(art))
            c.config(cursor='')

        def click(e):
            c.config(cursor='')
            SFX.play('select')
            cmd()
        c.tag_bind(i, '<Enter>', enter)
        c.tag_bind(i, '<Leave>', leave)
        c.tag_bind(i, '<Button-1>', click)
        self.menu_rows.append(([(sh, 'center', 2, 2), (i, 'center', 0)], ('art', i)))

    def m_option_plain(self, text, cmd, col):
        c = self.bgc
        i = c.create_text(0, 0, text=text, fill=col, font=(MONO, 16, 'bold'), tags='mnu', state='hidden')
        hot = mix(col, '#ffffff', 0.55)

        def enter(e):
            c.itemconfig(i, text='> %s <' % text, fill=hot)
            c.config(cursor='hand2')

        def leave(e):
            c.itemconfig(i, text=text, fill=col)
            c.config(cursor='')

        def click(e):
            c.config(cursor='')
            SFX.play('select')
            cmd()
        c.tag_bind(i, '<Enter>', enter)
        c.tag_bind(i, '<Leave>', leave)
        c.tag_bind(i, '<Button-1>', click)
        self.menu_rows.append(([(i, 'center', 0)], 46))

    def m_field(self, label, make_widget):
        c = self.bgc
        t = c.create_text(0, 0, text=label, fill='#cccccc', font=FONT, tags='mnu', state='hidden')
        w = make_widget(c)
        self.menu_widgets.append(w)
        i = c.create_window(0, 0, window=w, tags='mnu', state='hidden')
        self.menu_rows.append(([(t, 'e', -8), (i, 'w', 8)], 40))

    def build_menu_panel(self, page):
        c = self.bgc
        for w in getattr(self, 'menu_widgets', []):
            try:
                w.destroy()
            except tk.TclError:
                pass
        c.delete('mnu')
        c.config(cursor='')
        self.menu_widgets, self.menu_rows, self.menu_msg = [], [], None
        self.m_art = {}
        title, tcol = {'main': (self.u('subtitle'), '#999999'),
                       'single': (self.u('single_hdr'), '#55ff55'),
                       'multi': (self.u('multi_hdr'), '#ffff55')}[page]
        if page != 'main':
            self.m_text(title, tcol, (MONO, 12, 'bold'), 50)

        def name_entry(p):
            return tk.Entry(p, textvariable=self.name_var, font=FONT, bg='#111', fg='#fff',
                            insertbackground='#fff', width=16)

        def bots_spin(p):
            return tk.Spinbox(p, from_=1, to=3, textvariable=self.bots_var, width=3, font=FONT,
                              bg='#111', fg='#fff')
        if page == 'main':
            self.m_option(self.u('single'), lambda: self.menu_goto('single'), '#55ff55', art=True)
            self.m_option(self.u('multi'), lambda: self.menu_goto('multi'), '#ffff55', art=True)
            self.m_option(self.u('back_splash'), self.go_splash, '#ff7777', art=True)
        elif page == 'single':
            self.m_field(self.u('your_name'), name_entry)
            self.m_field(self.u('bots'), bots_spin)
            self.m_option(self.u('play'), self.start_single, '#55ff55')
            self.m_option(self.u('back_main'), lambda: self.menu_goto('main'), '#ff7777')
        else:
            self.m_field(self.u('your_name'), name_entry)
            self.m_option(self.u('host'), self.start_host, '#ffff55')
            self.menu_msg = self.m_text('', '#ff5555', SMALL, 34)
            self.m_option(self.u('back_main'), lambda: self.menu_goto('main'), '#ff7777')

    def layout_menu(self, w, top, h=None):
        c, cx = self.bgc, w / 2
        # ASCII-art options: biggest font that fits the window width
        hts = {}
        for i, (art, sh) in self.m_art.items():
            for size in (10, 9, 8):
                f = tkfont.Font(family=MONO, size=size, weight='bold')
                if f.measure('═') * (len(art[0]) + 8) <= w * 0.94:
                    break
            c.itemconfig(i, font=(MONO, size, 'bold'))
            c.itemconfig(sh, font=(MONO, size, 'bold'))
            hts[i] = f.metrics('linespace') * len(art) + 16
        rows = [(parts, hts[hh[1]] if isinstance(hh, tuple) else hh) for parts, hh in self.menu_rows]
        total = sum(hh for _, hh in rows)
        y = max(top, (h - total) / 2) if h else top      # menu centered in the window
        for parts, hh in rows:
            for part in parts:
                i, anchor, dx = part[:3]
                dy = part[3] if len(part) > 3 else 0
                c.coords(i, cx + dx, y + hh / 2 + dy)
                c.itemconfig(i, anchor=anchor, state='normal')
            y += hh
        c.tag_raise('mnu')

    def start_single(self):
        self.drain()
        self.build_game(net=False)
        self.backend = LocalBackend(self.pname(), self.bots_var.get(), self.lang, self.put_text, self.put_data)

    def start_host(self):
        if not self.server_started:
            self.server_started = True
            threading.Thread(target=Server(self.pname() + "'s server").serve, daemon=True).start()
        self.connect('127.0.0.1', TCP_PORT, host_ip=local_ip())

    def connect(self, ip, port, host_ip=None):
        if not ip:
            return
        self.drain()
        try:
            backend = NetBackend(ip, port, self.pname(), self.lang, self.put_text, self.put_data,
                                 lambda: self.q.put(('closed',)))
        except OSError as e:
            if self.menu_msg:
                self.bgc.itemconfig(self.menu_msg, text=self.u('conn_fail', ip=ip, port=port, err=e))
            return
        self.build_game(net=True)
        self.backend = backend
        if host_ip:
            self.write(self.u('lan_active', ip=host_ip), 'good')

    # ================= GAME =================
    def build_game(self, net):
        SFX.music_stop()
        self.clear()
        self.local, self.last_acts = not net, None
        self.ov, self.turn_on = None, False
        self.mode = 'lobby' if net else 'game'
        r = self.root
        r.columnconfigure(0, weight=1)
        r.rowconfigure(0, weight=1)

        left = tk.Frame(r, bg=BG)
        left.grid(row=0, column=0, sticky='nsew')
        left.rowconfigure(0, weight=1)
        left.columnconfigure(0, weight=1)
        self.con = tk.Text(left, bg=BG, fg='#c0c0c0', font=FONT, wrap='word', state='disabled', bd=0,
                           padx=8, pady=6, highlightthickness=0)
        sb = tk.Scrollbar(left, command=self.con.yview)
        self.con.config(yscrollcommand=sb.set)
        self.con.grid(row=0, column=0, sticky='nsew')
        sb.grid(row=0, column=1, sticky='ns')
        for k, c in TAGS.items():
            self.con.tag_config(k, foreground=c)
        self.con.tag_config('red', foreground='#ff5555', font=FONTB)
        self.con.tag_config('green', foreground='#55ff55')
        self.con.tag_config('magenta', foreground='#ff77ff')
        self.con.tag_config('warnb', foreground='#ffff55', font=FONTB)
        self.con.tag_config('cmdline', foreground='#ffffff')
        self.con.tag_config('head', foreground='#55ffff')

        self.acts = tk.Text(left, height=5, bg='#0b0b0b', bd=0, wrap='word', state='disabled', cursor='arrow',
                            padx=6, pady=4, highlightthickness=1, highlightbackground=LINE, font=SMALL, fg='#999')
        self.acts.grid(row=1, column=0, columnspan=2, sticky='ew')
        inf = tk.Frame(left, bg=BG)
        inf.grid(row=2, column=0, columnspan=2, sticky='ew', padx=8, pady=6)
        tk.Label(inf, text='>', font=FONTB, fg='#fff', bg=BG).pack(side='left')
        self.ent = tk.Entry(inf, font=FONT, bg=BG, fg='#fff', insertbackground='#fff', bd=0, highlightthickness=0)
        self.ent.pack(side='left', fill='x', expand=True, padx=6)
        self.ent.bind('<Return>', self.on_enter)
        self.ent.bind('<Up>', lambda e: self.history(-1))
        self.ent.bind('<Down>', lambda e: self.history(1))
        self.ent.focus_set()

        right = tk.Frame(r, bg=PANEL, width=344, highlightthickness=1, highlightbackground=LINE)
        right.grid(row=0, column=1, sticky='ns')
        right.pack_propagate(False)

        # lobby panel
        self.lobby_frame = tk.Frame(right, bg=PANEL)
        tk.Label(self.lobby_frame, text=self.u('lobby_title'), font=FONTB, fg='#55ffff', bg=PANEL).pack(pady=8)
        self.room_lb = tk.Listbox(self.lobby_frame, font=SMALL, bg='#050505', fg='#ddd', selectbackground='#335',
                                  highlightbackground=LINE, height=12)
        self.room_lb.pack(fill='x', padx=8)
        self.room_lb.bind('<Double-Button-1>', lambda e: self.join_room())
        bf = tk.Frame(self.lobby_frame, bg=PANEL)
        bf.pack(pady=8)
        self.btn(bf, self.u('create_room'), self.create_room, '#55ff55').pack(side='left', padx=3)
        self.btn(bf, self.u('join_room'), self.join_room, '#ffff55').pack(side='left', padx=3)
        self.btn(bf, self.u('refresh'), lambda: self.safe_send('roomsdata')).pack(side='left', padx=3)
        self.btn(self.lobby_frame, self.u('back'), self.exit_to_menu, '#ff7777').pack(side='bottom', pady=8)

        # game panel
        self.game_frame = tk.Frame(right, bg=PANEL)
        self.banner = tk.Label(self.game_frame, text='', font=(MONO, 13, 'bold'), bg='#222', fg='#aaa', pady=6)
        self.banner.pack(fill='x', padx=6, pady=(8, 4))
        self.warn = tk.Label(self.game_frame, text='', font=SMALL, fg='#ff5555', bg=PANEL)
        self.warn.pack()
        self.gunart = tk.Canvas(self.game_frame, width=330, height=64, bg=PANEL, highlightthickness=0)
        self.gunart.pack(padx=6)
        self.gunart.create_text(165, 32, text=GUN_ART, font=(MONO, 9), fill='#8a8a8a', tags='art')
        self.gunart.create_text(316, 17, text='-*-', font=(MONO, 14, 'bold'), fill='#ffdd55', tags='flash', state='hidden')
        tk.Label(self.game_frame, text=self.u('mag'), font=SMALL, fg='#55ffff', bg=PANEL).pack(anchor='w', padx=8)
        self.gun = tk.Canvas(self.game_frame, width=330, height=84, bg=PANEL, highlightthickness=0)
        self.gun.pack(padx=6)
        tk.Label(self.game_frame, text=self.u('players'), font=SMALL, fg='#55ffff', bg=PANEL).pack(anchor='w', padx=8, pady=(6, 0))
        self.pl = tk.Canvas(self.game_frame, width=330, height=200, bg=PANEL, highlightthickness=0)
        self.pl.pack(padx=6, fill='x')
        self.pl.bind('<MouseWheel>', lambda e: self.pl.yview_scroll(-1 * (e.delta // 120), 'units'))
        if net:
            self.btn(self.game_frame, self.u('leave_room'), lambda: self.safe_send('leave'), '#ff7777').pack(side='bottom', pady=8)
        else:
            self.btn(self.game_frame, self.u('back'), self.exit_to_menu, '#ff7777').pack(side='bottom', pady=8)

        if net:
            self.show_lobby_panel()
        else:
            self.show_game_panel()
        self.write(self.u('type_info'), 'info')
        self.pulse(self.gen)
        self.fade_in()

    def show_lobby_panel(self):
        self.mode = 'lobby'
        self.game_frame.pack_forget()
        self.lobby_frame.pack(fill='both', expand=True)
        self.render_actions([], self.u('lobby_hint'))
        self.safe_send('roomsdata')
        if not self.lobby_loop:
            self.lobby_loop = True
            self.root.after(3000, self.lobby_tick)

    def show_game_panel(self):
        self.mode = 'game'
        self.lobby_frame.pack_forget()
        self.game_frame.pack(fill='both', expand=True)

    def lobby_tick(self):
        if self.mode == 'lobby' and self.backend:
            self.safe_send('roomsdata')
            self.root.after(3000, self.lobby_tick)
        else:
            self.lobby_loop = False

    def safe_send(self, line):
        if self.backend:
            try:
                self.backend.send(line)
            except OSError:
                pass

    def create_room(self):
        name = simpledialog.askstring(self.u('create_room'), self.u('room_q'), parent=self.root)
        if not name:
            return
        n = simpledialog.askinteger(self.u('create_room'), self.u('max_q'), parent=self.root,
                                    initialvalue=4, minvalue=2, maxvalue=8)
        self.submit('create %s %d' % (name.replace(' ', '_'), n or 4))

    def join_room(self):
        sel = self.room_lb.curselection()
        if sel and sel[0] < len(self.rooms):
            self.submit('join ' + self.rooms[sel[0]]['name'])

    # ---- console ----
    def write(self, text, kind=None):
        c = self.con
        self.fx(text)
        c.config(state='normal')
        start = c.index('end-1c')
        for line in text.split('\n'):
            head = line.startswith('---')
            line = self.deco(line)
            if kind in TAGS:
                c.insert('end', line + '\n', kind)
            elif head:
                c.insert('end', line + '\n', 'head')
            elif line.startswith('> '):
                c.insert('end', line + '\n', 'cmdline')
            else:
                pos = 0
                for m in RX.finditer(line):
                    c.insert('end', line[pos:m.start()])
                    c.insert('end', m.group(0), INL[m.lastindex - 1][1])
                    pos = m.end()
                c.insert('end', line[pos:] + '\n')
        self.fadein_text(start, TAGS.get(kind, '#c0c0c0'))
        c.config(state='disabled')
        c.see('end')

    def flash(self, color):
        self.con.config(bg=color)
        self.root.after(140, lambda: self.con.winfo_exists() and self.con.config(bg=BG))

    def on_enter(self, e=None):
        t = self.ent.get().strip()
        self.ent.delete(0, 'end')
        if t:
            self.hist.append(t)
            self.hi = len(self.hist)
            self.submit(t)

    def history(self, d):
        if not self.hist:
            return
        self.hi = max(0, min(len(self.hist), self.hi + d))
        self.ent.delete(0, 'end')
        if self.hi < len(self.hist):
            self.ent.insert(0, self.hist[self.hi])

    def submit(self, line):
        low = line.lower().strip()
        if low in ('clear', 'cls'):
            self.con.config(state='normal')
            self.con.delete('1.0', 'end')
            self.con.config(state='disabled')
            return
        if low in ('quit', 'exit') or (self.local and low in ('leave', 'salir', 'lobby')):
            return self.exit_to_menu()
        self.write('> ' + line)
        self.safe_send(line)

    # ---- server data ----
    def on_data(self, d):
        t = d.get('type')
        if t == 'lobby' and not self.local:
            self.show_lobby_panel()
        elif t == 'rooms':
            self.rooms = d['rooms']
            self.room_lb.delete(0, 'end')
            for r in self.rooms:
                self.room_lb.insert('end', self.u('room_row', name=r['name'], n=r['n'], max=r['max'],
                                                  st=self.u('st_play' if r['started'] else 'st_wait'),
                                                  host=r['host']))
        elif t == 'game':
            if self.mode != 'game':
                self.show_game_panel()
            self.render(d)

    def render(self, d):
        started = d['started']
        self.turn_on = bool(started and d['my_turn'])
        if not started:
            self.banner.config(text=self.u('room_banner', room=d['room'], n=len(d['players']), max=d['maxp']),
                               bg='#222', fg='#aaa')
        elif d['my_turn']:
            self.banner.config(text=self.u('your_turn'), bg='#555500', fg='#ffff55')
        else:
            self.banner.config(text=self.u('turn_of', name=d['turn']), bg='#222', fg='#aaa')
        self.warn.config(text=self.u('sawed_warn', name=d['sawed']) if d['sawed'] and started else '')
        self.draw_gun(d)
        self.draw_players(d)
        self.render_actions(self.actions(d), None if (d['my_turn'] or not started) else
                            self.u('waiting', name=d['turn']))

    def draw_gun(self, d):
        c = self.gun
        c.delete('all')
        if not d['started']:
            c.create_text(165, 40, text=self.u('no_game'), fill='#777', font=FONT)
            return
        n = d['shells']
        w = min(26, 300 // max(n, 1))
        for i in range(n):
            x0 = 10 + i * (w + 5)
            c.create_rectangle(x0, 6, x0 + w, 48, fill='#b8902a', outline='#e8c860')
            c.create_rectangle(x0, 36, x0 + w, 48, fill='#7a5c12', outline='')
            c.create_text(x0 + w / 2, 21, text='?', fill='#201500', font=FONTB)
        c.create_rectangle(10, 58, 22, 70, fill='#ff5555', outline='')
        c.create_text(28, 56, anchor='nw', text=self.u('live_n', n=d['live']), fill='#ff5555', font=SMALL)
        c.create_rectangle(130, 58, 142, 70, fill='#55ff55', outline='')
        c.create_text(148, 56, anchor='nw', text=self.u('blank_n', n=d['blank']), fill='#55ff55', font=SMALL)
        c.create_text(10, 74, anchor='nw', text=self.u('reload_info', r=d['round'], l=d['live0'], b=d['blank0']),
                      fill='#777', font=(MONO, 8))

    def draw_players(self, d):
        c = self.pl
        c.delete('all')
        y = 4
        for p in d['players']:
            on_turn = p['turn'] and d['started'] and p['alive']
            col = '#777' if not p['alive'] else ('#ff77ff' if p['bot'] else '#ffffff')
            label = ('>> ' if on_turn else '   ') + p['name'] + (self.u('you') if p['name'] == d['you'] else '')
            c.create_text(6, y, anchor='nw', text=label, fill='#ffff55' if on_turn else col, font=FONTB)
            flags = (self.u('cuffed') if p['cuffed'] else '') + ('' if p['alive'] else self.u('dead'))
            c.create_text(326, y + 2, anchor='ne', text=self.u('wins', n=p['score']) + flags, fill='#999', font=SMALL)
            ratio = p['hp'] / float(p['maxhp'] or 1)
            hc = '#ff5555' if ratio <= 0.34 else ('#ffff55' if ratio <= 0.6 else '#55ff55')
            for i in range(p['maxhp']):
                c.create_rectangle(8 + i * 24, y + 24, 28 + i * 24, y + 36, outline='#444', fill=hc if i < p['hp'] else '#222')
            c.create_text(14 + p['maxhp'] * 24, y + 23, anchor='nw', text='%d/%d HP' % (p['hp'], p['maxhp']), fill=col, font=SMALL)
            face = '(x_x)' if not p['alive'] else ('(>_<)' if ratio <= 0.34 else ('(o_o)' if ratio <= 0.6 else '(^_^)'))
            if p['bot']:
                face = '[' + face[1:-1] + ']'
            c.create_text(326, y + 23, anchor='ne', text=face, fill=col, font=SMALL)
            its = ', '.join('%s x%d' % (self.iname(k), v) for k, v in p['items'].items())
            c.create_text(8, y + 42, anchor='nw', width=316, text=its or self.u('no_items'),
                          fill='#55ffff' if its else '#555', font=SMALL)
            y += 76
        c.config(scrollregion=(0, 0, 330, y), height=max(10, min(y, 400)))

    # ---- action buttons ----
    def actions(self, d):
        acts = []
        i = li(self.lang)
        me = next((p for p in d['players'] if p['name'] == d['you']), None)
        if not d['started']:
            if d['host'] == d['you']:
                acts += [('>> START', 'start', 'host', self.u('start_tip')),
                         ('+ BOT', 'addbot', 'host', self.u('bot_tip'))]
            return acts
        if not d['my_turn'] or d['pending'] or not me or not me['alive']:
            return acts
        riv = [p for p in d['players'] if p['name'] != me['name'] and p['alive']]
        acts.append((self.u('shoot_me'), 'shoot me', 'shoot', self.u('shoot_me_tip')))
        for r in riv:
            acts.append((self.u('shoot_at', name=r['name']), 'shoot ' + r['name'], 'shoot', self.u('shoot_tip')))
        for k in ITEMS:
            v = me['items'].get(k, 0)
            lab, desc = ITEMS[k][i], ITEMS[k][2 + i]
            if not v:
                continue
            if k == 'handcuffs':
                for r in riv:
                    if not r['cuffed']:
                        acts.append(('%s x%d > %s' % (lab, v, r['name']), 'use handcuffs ' + r['name'], 'item', desc))
            elif k == 'adrenaline':
                for r in riv:
                    for k2 in r['items']:
                        if k2 != 'adrenaline':
                            acts.append((self.u('adr_btn', item=self.iname(k2), name=r['name']),
                                         'use adrenaline %s %s' % (r['name'], k2), 'item', desc))
            elif k == 'cigarettes' and me['hp'] >= me['maxhp']:
                continue
            elif k == 'saw' and d['sawed'] == me['name']:
                continue
            elif k == 'phone' and d['shells'] < 2:
                continue
            else:
                acts.append(('%s x%d' % (lab, v), 'use ' + k, 'item', desc))
        return acts

    def render_actions(self, acts, hint):
        sig = repr((acts, hint))
        if sig == self.last_acts:
            return
        self.last_acts = sig
        a = self.acts
        a.config(state='normal')
        a.delete('1.0', 'end')
        for w in list(a.children.values()):
            w.destroy()
        if acts:
            if acts[0][2] != 'host':
                a.insert('end', self.u('pick') + '\n')
            for lab, cmd, kind, tip in acts:
                fg, bd = {'shoot': ('#ff7777', '#aa3333'), 'item': ('#55ffff', '#338888'), 'host': ('#ffff55', '#888833')}[kind]
                b = self.btn(a, lab, lambda c=cmd: self.submit(c), fg, bd)
                Tip(b, tip)
                a.window_create('end', window=b, padx=2, pady=2)
        elif hint:
            a.insert('end', hint)
        a.config(state='disabled')

    def run(self):
        self.root.mainloop()


# ====================== START ======================
if __name__ == '__main__':
    if len(sys.argv) > 1 and sys.argv[1] == 'server':
        print('Server on %s:%d (Ctrl+C to stop).' % (local_ip(), TCP_PORT))
        try:
            Server(socket.gethostname()).serve()
        except KeyboardInterrupt:
            pass
    elif tk is None:
        print('Tkinter is not available. Use: python buckshot.py server')
    else:
        App().run()
